import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider the polynomial in {dimension} variables defined by {poly_text}. All coefficients are positive integers. Determine the smallest positive integer n such that, after like terms are collected, the expansion of [P(x_1, ..., x_{dimension})]^n has at least {target_terms} distinct monomials.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# choose dimension 3 or 4 (3 more frequent to keep instances readable)
d = rng.choice([3, 3, 4])
varsyms = ['x', 'y', 'z', 'w'][:d]
# choose exponents >= 1 to avoid trivialities; prefer >1 for disguise
exps = [rng.randint(2, 7) for _ in range(d)]
# choose positive integer coefficients for each of the 2^d vertex monomials
num_terms = 1 << d
coeffs = [rng.randint(1, 9) for _ in range(num_terms)]

# build polynomial text for all subsets of variables (cube/cuboid vertices)
def monomial_str(mask):
    parts = []
    for i in range(d):
        if (mask >> i) & 1:
            e = exps[i]
            v = varsyms[i]
            parts.append(f"{v}^{e}")
    if not parts:
        return "1"  # empty subset -> constant term
    return "*".join(parts)

terms = []
for mask in range(num_terms):
    c = coeffs[mask]
    mono = monomial_str(mask)
    if mono == "1":
        term = f"{c}"
    else:
        if c == 1:
            term = mono
        else:
            term = f"{c}*{mono}"
    terms.append(term)

poly_core = " + ".join(terms)
vars_list = ", ".join(varsyms)
poly_text = f"P({vars_list}) = {poly_core}"

# choose a target so that minimal n is controlled and nontrivial
# pick desired answer n_star, then pick target in (n_star^d, (n_star+1)^d]
n_star = rng.randint(8, 120)
low = (n_star)**d + 1
high = (n_star + 1)**d
target_terms = rng.randint(low, high)

return {
    'dimension': d,
    'poly_text': poly_text,
    'target_terms': target_terms,
    # hidden structure for verifier
    'varsyms': varsyms,
    'exponents': exps,
    'coeffs': coeffs
}

    def verifier(assign):
# basic key checks
required_keys = ['dimension', 'poly_text', 'target_terms', 'varsyms', 'exponents', 'coeffs']
for k in required_keys:
    if k not in assign:
        # missing data
        return (False, None)
d = assign['dimension']
poly_text = assign['poly_text']
target = assign['target_terms']
varsyms = assign['varsyms']
exps = assign['exponents']
coeffs = assign['coeffs']

# domain validation
if not isinstance(d, int) or d < 3 or d > 4:
    # enforce harder-than-seed by requiring at least 3 variables
    return (False, None)
if not isinstance(target, int) or target < 1:
    return (False, None)
if not isinstance(poly_text, str) or len(poly_text) == 0:
    return (False, None)
if not isinstance(varsyms, list) or len(varsyms) != d:
    return (False, None)
if not isinstance(exps, list) or len(exps) != d:
    return (False, None)
if not all(isinstance(e, int) and e >= 1 for e in exps):
    return (False, None)
if not isinstance(coeffs, list) or len(coeffs) != (1 << d):
    return (False, None)
if not all(isinstance(c, int) and c > 0 for c in coeffs):
    return (False, None)

# structural note: polynomial is sum over all 2^d vertex monomials with positive coefficients.
# This ensures no cancellation and the exponent set equals {0, e_i} for each coordinate.

# Compute minimal n such that (n+1)^d >= target using integer binary search to avoid FP issues.
def minimal_n(target, d):
    lo = -1
    hi = target  # (hi+1)^d >= target trivially
    while hi - lo > 1:
        mid = (lo + hi) // 2
        val = (mid + 1) ** d
        if val >= target:
            hi = mid
        else:
            lo = mid
    return hi

answer = minimal_n(target, d)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

